10	/** Địa chỉ yêu cầu (giữ dấu phẩy trong danh sách biến, mã hóa `/` của múi giờ). */
11	export function envUrl(cfg: { api: string; lat: number; lon: number; tz: string }): string {
12	  return cfg.api + '?latitude=' + cfg.lat + '&longitude=' + cfg.lon
13	    + '&current=' + CURRENT + '&daily=sunrise,sunset'
14	    + '&timezone=' + encodeURIComponent(cfg.tz) + '&wind_speed_unit=kmh&forecast_days=1';
15	}
