20	/** "2026-11-14T22:15" → { utc: epoch ms nếu coi chuỗi là UTC, min: phút trong ngày } */
21	function envLocalTime(s: unknown): { utc: number; min: number } | null {
22	  if (typeof s !== 'string') return null;
23	  const m = TIME_RE.exec(s);
24	  if (!m) return null;
25	  const h = +m[4], mi = +m[5];
26	  return { utc: Date.UTC(+m[1], +m[2] - 1, +m[3], h, mi), min: h * 60 + mi };
27	}
