29	/** Phản hồi → số liệu; null khi thiếu giờ quan trắc hoặc số bắt buộc không hữu hạn. UV / mọc / lặn thiếu thì null. */
30	export function envParse(json: unknown): EnvWeather | null {
31	  const j: any = json;
32	  if (!j || typeof j !== 'object') return null;
33	  const c = j.current;
34	  if (!c || typeof c !== 'object') return null;
35	  const t = envLocalTime(c.time);
36	  if (!t) return null;
37	  const need = [c.temperature_2m, c.apparent_temperature, c.relative_humidity_2m, c.wind_speed_10m, c.wind_direction_10m, c.precipitation, c.cloud_cover, c.weather_code];
38	  if (!need.every(num)) return null;
39	  const off = (num(j.utc_offset_seconds) ? j.utc_offset_seconds : ICT_OFFSET_S) * 1000;
40	  const sr = envLocalTime(j.daily && j.daily.sunrise && j.daily.sunrise[0]);
41	  const ss = envLocalTime(j.daily && j.daily.sunset && j.daily.sunset[0]);
42	  return {
43	    obs: t.utc - off, obsMin: t.min,
44	    temp: c.temperature_2m, feels: c.apparent_temperature, hum: c.relative_humidity_2m,
45	    wind: c.wind_speed_10m, dir: c.wind_direction_10m, rain: c.precipitation, cloud: c.cloud_cover,
46	    uv: num(c.uv_index) ? c.uv_index : null, code: c.weather_code, isDay: c.is_day === 1 || c.is_day === true,
47	    sunrise: sr ? sr.min : null, sunset: ss ? ss.min : null
48	  };
49	}
