51	/** Kiểm đối tượng (từ bộ nhớ đệm) đúng kiểu EnvWeather: cùng phép kiểm số như envParse. */
52	export function envIsWeather(x: unknown): x is EnvWeather {
53	  const o: any = x;
54	  if (!o || typeof o !== 'object') return false;
55	  const nn = (v: unknown) => v === null || num(v);
56	  return [o.obs, o.obsMin, o.temp, o.feels, o.hum, o.wind, o.dir, o.rain, o.cloud, o.code].every(num)
57	    && nn(o.uv) && nn(o.sunrise) && nn(o.sunset) && typeof o.isDay === 'boolean';
58	}
