60	/** Mã WMO → khóa i18n + biểu tượng; mã lạ như mã 2 (có mây). */
61	export function envWx(code: number, isDay: boolean): { key: string; icon: EnvIcon } {
62	  const dn = isDay ? 'd' : 'n';
63	  if (code === 0) return { key: isDay ? 'envWxClearD' : 'envWxClearN', icon: ('clear-' + dn) as EnvIcon };
64	  if (code === 1) return { key: isDay ? 'envWxFewD' : 'envWxFewN', icon: ('cloudy-' + dn) as EnvIcon };
65	  if (code === 3) return { key: 'envWxOvercast', icon: 'cloud' };
66	  if (code === 45 || code === 48) return { key: 'envWxFog', icon: 'fog' };
67	  if (code >= 51 && code <= 57) return { key: 'envWxDrizzle', icon: 'rain' };
68	  if (code === 61 || code === 66 || code === 80) return { key: 'envWxRainL', icon: 'rain' };
69	  if (code === 63 || code === 81) return { key: 'envWxRainM', icon: 'rain' };
70	  if (code === 65 || code === 67 || code === 82) return { key: 'envWxRainH', icon: 'rain' };
71	  if ((code >= 71 && code <= 77) || code === 85 || code === 86) return { key: 'envWxSnow', icon: 'snow' };
72	  if (code >= 95 && code <= 99) return { key: 'envWxStorm', icon: 'storm' };
73	  return { key: 'envWxPartly', icon: ('cloudy-' + dn) as EnvIcon };
74	}
75	
76	const COMPASS = ['N', 'NE', 'E', 'SE', 'S', 'SW', 'W', 'NW'] as const;
77	
78	/** Hướng gió (độ, hướng gió thổi TỪ đó tới) → 8 hướng; nhận cả số âm / quá 360. */
79	export function envCompass(deg: number): 'N' | 'NE' | 'E' | 'SE' | 'S' | 'SW' | 'W' | 'NW' {
80	  const d = ((deg % 360) + 360) % 360;
81	  return COMPASS[Math.floor((d + 22.5) / 45) % 8];
82	}
83	
