85	export function envUvLevel(uv: number): '' | 'Low' | 'Mod' | 'High' | 'VHigh' | 'Ext' {
86	  if (!(uv > 0)) return '';
87	  if (uv < 3) return 'Low';
88	  if (uv < 6) return 'Mod';
89	  if (uv < 8) return 'High';
90	  if (uv < 11) return 'VHigh';
91	  return 'Ext';
92	}
