1	import { CONFIG } from '../../config';
2	import { rng } from '../../common/math';
3	
4	/* ===== [weather] Trạng thái thời tiết: tham số liên tục, preset, tiến dần về target, nhiễu gió =====
5	   Module THUẦN: không import three/scene. Ngẫu nhiên dùng rng(CONFIG.weather.seed + k), KHÔNG dùng rand(). */
6	export interface WeatherParams {
7	  temp: number;      // °C — nhiệt độ không khí
8	  rain: number;      // 0 → 1 — cường độ mưa
9	  wind: number;      // m/s ở 10 m — gió trung bình
10	  gust: number;      // m/s — biên độ gió giật cộng thêm
11	  windDir: number;   // rad — hướng gió THỔI TỚI (0 = sang +X)
12	  cloud: number;     // 0 → 1 — độ phủ mây
13	  haze: number;      // 0 → 1 — mù nóng
14	  level: number;     // m — mực nước sông dâng thêm
15	  lightning: number; // 0 → 1 — tần suất chớp
16	  closed: boolean;   // cấm lưu thông qua cầu (theo trạng thái preset / kịch bản, không theo ngưỡng gió)
17	}
18	export type PresetName = 'now' | 'summer' | 'rain' | 'monsoon' | 'storm';
19	export const PRESET_NAMES: PresetName[] = ['now', 'summer', 'rain', 'monsoon', 'storm'];
20	
21	export interface WeatherState {
22	  current: WeatherParams; target: WeatherParams;
23	  wet: number;            // 0 → 1 — mặt ướt (dẫn xuất: lên nhanh theo mưa, khô chậm)
24	  preset: PresetName; intensity: number;   // 0 → 1 — thanh cường độ nhân lên rain/wind/gust/level
25	}
26	
27	/* Giá trị trung tính (không mưa, không gió): đích của preset `now`. */
28	export const neutralParams = (): WeatherParams => ({ temp: CONFIG.weather.thermal.refTemp, rain: 0, wind: 0, gust: 0, windDir: CONFIG.weather.windDir, cloud: 0, haze: 0, level: 0, lightning: 0, closed: false });
29	
30	export const createWeatherState = (): WeatherState => ({ current: neutralParams(), target: neutralParams(), wet: 0, preset: 'now', intensity: 1 });
31	
32	/* Đích của một preset sau khi nhân thanh cường độ k (0–1). `now` -> trung tính. */
33	export function presetTarget(name: PresetName, k = 1): WeatherParams {
34	  const p = CONFIG.weather.presets[name], n = neutralParams();
35	  if (!p) return n;
36	  const kk = Math.max(0, Math.min(1, k));
37	  return { ...n, ...p, rain: p.rain * kk, wind: p.wind * kk, gust: p.gust * kk, level: p.level * kk };
38	}
39	
40	export function setPreset(s: WeatherState, name: PresetName, k = s.intensity) {
41	  s.preset = name; s.intensity = Math.max(0, Math.min(1, k));
42	  s.target = presetTarget(name, s.intensity);
43	}
44	
45	const approach = (a: number, b: number, tau: number, dt: number) => b + (a - b) * Math.exp(-dt / Math.max(1e-3, tau));
46	
47	/* Tiến current về target theo hằng số thời gian riêng từng tham số (giống stepNight). */
48	export function stepWeather(s: WeatherState, dt: number) {
49	  const T = CONFIG.weather.tau, c = s.current, t = s.target;
50	  c.temp = approach(c.temp, t.temp, T.temp, dt);
51	  c.rain = approach(c.rain, t.rain, T.rain, dt);
52	  c.wind = approach(c.wind, t.wind, T.wind, dt);
53	  c.gust = approach(c.gust, t.gust, T.wind, dt);
54	  c.windDir = t.windDir;
55	  c.cloud = approach(c.cloud, t.cloud, T.cloud, dt);
56	  c.haze = approach(c.haze, t.haze, T.haze, dt);
57	  c.level = approach(c.level, t.level, T.level, dt);
58	  c.lightning = approach(c.lightning, t.lightning, T.lightning, dt);
59	  c.closed = t.closed;
60	  s.wet = approach(s.wet, c.rain, c.rain > s.wet ? T.rain : T.wet, dt);   // ướt nhanh, khô chậm
61	}
62	
63	/* Nhiễu gió giật g(t) ∈ [0, 1]: tổng vài tầng nội suy cosin trên bảng ngẫu nhiên có seed (lặp tuần hoàn, không dùng rand()). */
64	let gustTable: number[][] | null = null;
65	function gustTables() {
66	  if (gustTable) return gustTable;
67	  const G = CONFIG.weather.gust, rnd = rng(CONFIG.weather.seed + 1);
68	  gustTable = Array.from({ length: G.octaves }, () => Array.from({ length: G.steps }, () => rnd()));
69	  return gustTable;
70	}
71	export function gustNoise(t: number): number {
72	  const G = CONFIG.weather.gust, tabs = gustTables();
73	  let sum = 0, amp = 1, norm = 0;
74	  for (let o = 0; o < G.octaves; o++) {
75	    const x = Math.abs(t) / (G.period / (1 << o)), i = Math.floor(x), f = x - i, a = tabs[o][i % G.steps], b = tabs[o][(i + 1) % G.steps], u = (1 - Math.cos(f * Math.PI)) / 2;
76	    sum += (a + (b - a) * u) * amp; norm += amp; amp *= 0.5;
77	  }
78	  return sum / norm;
79	}
80	/* Gió tức thời ở 10 m: trung bình + giật. */
81	export const windNow = (c: WeatherParams, t: number) => c.wind + c.gust * gustNoise(t);
82

